import{_ as t,o as h,c as i,ae as c}from"./chunks/framework.BONZgKEB.js";const p=JSON.parse('{"title":"Thiết lập Thi đấu & Lịch trình","description":"","frontmatter":{},"headers":[],"relativePath":"vi/guide/competition-setup.md","filePath":"vi/guide/competition-setup.md"}'),a={name:"vi/guide/competition-setup.md"};function o(g,n,l,r,e,u){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="thiet-lap-thi-đau-lich-trinh" tabindex="-1">Thiết lập Thi đấu &amp; Lịch trình <a class="header-anchor" href="#thiet-lap-thi-đau-lich-trinh" aria-label="Permalink to &quot;Thiết lập Thi đấu &amp; Lịch trình&quot;">​</a></h1><p>Sau khi tạo thành công một sự kiện và đăng ký vận động viên, bước tiếp theo là cấu hình các cuộc thi. Một sự kiện đơn lẻ thường được chia thành nhiều cuộc thi dựa trên thiết bị và giới tính (ví dụ: Cung 1 dây Nam, Cung trợ lực Nữ).</p><h2 id="_1-hieu-ve-cac-cuoc-thi" tabindex="-1">1. Hiểu về các Cuộc thi <a class="header-anchor" href="#_1-hieu-ve-cac-cuoc-thi" aria-label="Permalink to &quot;1. Hiểu về các Cuộc thi&quot;">​</a></h2><p>Điều hướng đến tab <strong>Cuộc thi</strong> trong Bảng điều khiển Sự kiện của bạn. Tại đây bạn sẽ thấy danh sách tất cả các cuộc thi đang hoạt động cho sự kiện của mình.</p><p>Việc chọn một cuộc thi cụ thể sẽ đưa bạn đến <strong>Bảng điều khiển Cuộc thi</strong>, nơi bạn quản lý hai giai đoạn chính của một giải đấu bắn cung:</p><ol><li><strong>Vòng Phân hạng</strong></li><li><strong>Vòng Loại trực tiếp</strong></li></ol><h2 id="_2-thiet-lap-vong-ban-phan-hang" tabindex="-1">2. Thiết lập Vòng Bắn Phân hạng <a class="header-anchor" href="#_2-thiet-lap-vong-ban-phan-hang" aria-label="Permalink to &quot;2. Thiết lập Vòng Bắn Phân hạng&quot;">​</a></h2><p>Vòng Phân hạng là nơi các vận động viên bắn một số lượng mũi tên nhất định để xác định thứ hạng và hạt giống của họ cho Vòng Loại trực tiếp.</p><h3 id="phan-cong-bia" tabindex="-1">Phân công Bia <a class="header-anchor" href="#phan-cong-bia" aria-label="Permalink to &quot;Phân công Bia&quot;">​</a></h3><p>Trước khi việc ghi điểm có thể bắt đầu, ban tổ chức phải phân công các vận động viên vào các bia cụ thể trên sân.</p><ol><li>Điều hướng đến phần <strong>Lịch trình</strong> hoặc <strong>Thiết lập</strong> trong Cuộc thi của bạn.</li><li>Chọn <strong>Thiết lập Phân hạng</strong>.</li><li>Bạn sẽ thấy danh sách tất cả các vận động viên đã đăng ký cho hạng mục này.</li><li><strong>Phân công Bia:</strong> Nhập ID Bia (ví dụ: &quot;1A&quot;, &quot;2B&quot;) cho mỗi vận động viên. <ul><li><em>Mẹo: Ứng dụng giúp bạn tổ chức các vận động viên bằng cách đảm bảo không có hai vận động viên nào được phân công cùng một vị trí bia trong cùng một thời điểm.</em></li></ul></li><li><strong>Lưu Phân công:</strong> Khi tất cả các vận động viên đã được phân công, hãy nhấp vào lưu.</li></ol><p>Việc phân công này xác định bảng điểm kỹ thuật số nào mà vận động viên hoặc trọng tài được phân công của họ sẽ có quyền truy cập trong suốt vòng đấu.</p><h2 id="_3-thiet-lap-vong-ban-loai" tabindex="-1">3. Thiết lập Vòng Bắn Loại <a class="header-anchor" href="#_3-thiet-lap-vong-ban-loai" aria-label="Permalink to &quot;3. Thiết lập Vòng Bắn Loại&quot;">​</a></h2><p>Sau khi vòng Phân hạng hoàn tất và tất cả các điểm số được chốt, hệ thống có thể xác định thứ hạng của các vận động viên. Những thứ hạng này được sử dụng để xếp hạt giống cho sơ đồ đấu Loại.</p><h3 id="tao-so-đo-thi-đau" tabindex="-1">Tạo Sơ đồ thi đấu <a class="header-anchor" href="#tao-so-đo-thi-đau" aria-label="Permalink to &quot;Tạo Sơ đồ thi đấu&quot;">​</a></h3><ol><li>Đảm bảo Vòng Phân hạng được đánh dấu là <strong>Đã hoàn thành</strong>.</li><li>Điều hướng đến phần <strong>Thiết lập Vòng loại</strong>.</li><li>Chọn thể thức thi đấu loại (ví dụ: Loại Cá nhân).</li><li><strong>Tạo Sơ đồ thi đấu:</strong> Hệ thống sẽ tự động xây dựng cây thi đấu. Cung thủ xếp hạng số 1 sẽ thi đấu với cung thủ xếp hạng thấp nhất, số 2 thi đấu với người xếp hạng thấp thứ hai, và cứ tiếp tục như vậy, tuân theo luật tạo sơ đồ tiêu chuẩn của Bắn cung Thế giới.</li><li><strong>Xem xét các Trận đấu:</strong> Bạn có thể xem lại các cặp đấu được tạo trước khi chính thức bắt đầu Vòng Loại.</li></ol><h3 id="quan-ly-cac-luot-đac-cach-byes" tabindex="-1">Quản lý các lượt đặc cách (Byes) <a class="header-anchor" href="#quan-ly-cac-luot-đac-cach-byes" aria-label="Permalink to &quot;Quản lý các lượt đặc cách (Byes)&quot;">​</a></h3><p>Nếu số lượng vận động viên không phải là lũy thừa hoàn hảo của hai (ví dụ: 16, 32, 64), hệ thống sẽ tự động cấp quyền <strong>Đặc cách</strong> cho các vận động viên được xếp hạt giống cao nhất, cho phép họ tự động tiến vào vòng tiếp theo.</p><p>👉 <em>Bước tiếp theo:</em> <a href="./scoring-workflow.html">Tìm hiểu về Quy trình Ghi điểm</a></p>',19)])])}const v=t(a,[["render",o]]);export{p as __pageData,v as default};
